    ).run(id, payload.input, payload.steps, payload.failAttempts, key, now, now);
    const row = getRowById(db, id);
    if (!row) throw new Error('inserted job not found');
    return { kind: 'created', job: toPublicJob(row) };
  });
}

// ---- worker side -------------------------------------------------------------------------------

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO worker_state (id, heartbeat_at) VALUES (1, ?)
     ON CONFLICT(id) DO UPDATE SET heartbeat_at = excluded.heartbeat_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('UPDATE worker_state SET heartbeat_at = NULL WHERE id = 1').run();
}

export function isWorkerUp(db: DatabaseSync, now: number): boolean {
  const row = db.prepare('SELECT heartbeat_at FROM worker_state WHERE id = 1').get() as
    | { heartbeat_at: number | null }
    | undefined;
  return row?.heartbeat_at != null && now - row.heartbeat_at <= HEARTBEAT_FRESH_MS;
}

/**
 * Claims the next unit of work. A job left `running` belongs to an interrupted worker, so it is
 * replayed first with its persisted attempt number. Otherwise the oldest eligible queued job starts
 * a new attempt.
 */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  const stamp = new Date(now).toISOString();
  const hasWork = db
    .prepare(
      `SELECT 1 FROM jobs WHERE status = 'running' OR (status = 'queued' AND available_at <= ?) LIMIT 1`,
    )
    .get(now);
  if (!hasWork) return undefined;

  return transaction(db, (): JobRow | undefined => {
    const running = db.prepare(`SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1`).get() as
      | JobRow
      | undefined;
    if (running) {
      db.prepare('UPDATE jobs SET completed_steps = 0, updated_at = ? WHERE seq = ?').run(stamp, running.seq);
      return { ...running, completed_steps: 0 };
    }
    const queued = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`)
      .get(now) as JobRow | undefined;
    if (!queued) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0,
                       output = NULL, error = NULL, updated_at = ?
       WHERE seq = ?`,
    ).run(stamp, queued.seq);
    return { ...queued, status: 'running', attempts: queued.attempts + 1, completed_steps: 0 };
  });
}

export function recordProgress(db: DatabaseSync, seq: number, completed: number): void {
  transaction(db, () => {
    db.prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE seq = ? AND status = 'running'`).run(
      completed,
      new Date().toISOString(),
      seq,
    );
  });
}

export function completeJob(db: DatabaseSync, seq: number, output: string, steps: number): void {
  transaction(db, () => {
    db.prepare(
      `UPDATE jobs SET status = 'completed', completed_steps = ?, output = ?, error = NULL, updated_at = ?
       WHERE seq = ? AND status = 'running'`,
    ).run(steps, output, new Date().toISOString(), seq);
  });
}

/** Handles a simulated transient failure: requeue with a delay, or fail after the last attempt. */
export function recordTransientFailure(db: DatabaseSync, seq: number, attempts: number, now: number): void {
  transaction(db, () => {
    const stamp = new Date(now).toISOString();
    if (attempts < MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'queued', completed_steps = 0, available_at = ?, updated_at = ?
         WHERE seq = ? AND status = 'running'`,
      ).run(now + RETRY_DELAY_MS, stamp, seq);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL,
                         error = 'transient failure', updated_at = ?
         WHERE seq = ? AND status = 'running'`,
      ).run(stamp, seq);
    }
  });
}

