import type { NewJob } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type SubmissionResult =
  | { ok: true; payload: NewJob; key: string | null }
  | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Validates a job submission. Every offending field is reported, not just the first one. Defaults
 * are applied only to absent properties.
 */
export function validateSubmission(
  contentType: string | undefined,
  bodyText: string,
  idempotencyKey: string | undefined,
): SubmissionResult {
  const fields: FieldError[] = [];

  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  let parsed: unknown;
  let parsedOk = true;
  try {
    parsed = JSON.parse(bodyText);
  } catch {
    parsedOk = false;
  }
  if (!parsedOk || !isObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
  }

  let payload: NewJob | undefined;
  if (parsedOk && isObject(parsed)) {
    for (const key of Object.keys(parsed)) {
      if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
    }

    let input: string | undefined;
    if (!Object.hasOwn(parsed, 'input')) {
      fields.push({ field: 'input', message: 'is required' });
    } else {
      const value = parsed.input;
      if (
        typeof value !== 'string' ||
        value.length < 1 ||
        value.length > 1000 ||
        value.trim().length === 0
      ) {
        fields.push({
          field: 'input',
          message: 'must be a string of 1 to 1000 characters that is not only whitespace',
        });
      } else {
        input = value;
      }
    }

    const steps = integerField(parsed, 'steps', 1, 20, 5, fields);
    const failAttempts = integerField(parsed, 'failAttempts', 0, 5, 0, fields);

    if (input !== undefined && steps !== undefined && failAttempts !== undefined) {
      payload = { input, steps, failAttempts };
    }
  }

  let key: string | null = null;
  if (idempotencyKey !== undefined) {
    if (IDEMPOTENCY_KEY_RE.test(idempotencyKey)) {
      key = idempotencyKey;
    } else {
      fields.push({
        field: 'Idempotency-Key',
        message: 'must be 1 to 128 characters of letters, digits, underscores, or hyphens',
      });
    }
  }

  if (fields.length > 0 || payload === undefined) {
    return { ok: false, fields };
  }
  return { ok: true, payload, key };
}

function integerField(
  obj: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) {
    return value;
  }
  fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  return undefined;
}

