import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, isWorkerUp, listJobs, submitJob } from './jobs.ts';
import { validateSubmission, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 64 * 1024;
const SHUTDOWN_GRACE_MS = 2000;
const SHUTDOWN_DEADLINE_MS = 4000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields !== undefined) error.fields = fields;
  sendJson(res, status, { error });
}

/** Reads the whole body. Returns undefined when it exceeds the size limit. */
async function readBody(req: IncomingMessage): Promise<string | undefined> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > MAX_BODY_BYTES) return undefined;
    chunks.push(buf);
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function handleSubmit(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  const headerKey = req.headers['idempotency-key'];
  const idempotencyKey = typeof headerKey === 'string' ? headerKey : undefined;
  if (text === undefined) {
    sendError(res, 400, 'invalid_request', 'Request is invalid.', [
      { field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` },
    ]);
    return;
  }
  const checked = validateSubmission(req.headers['content-type'], text, idempotencyKey);
  if (!checked.ok) {
    sendError(res, 400, 'invalid_request', 'Request is invalid.', checked.fields);
    return;
  }
  const outcome = submitJob(db, checked.payload, checked.key);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

interface Route {
  methods: readonly string[];
  handle: (req: IncomingMessage, res: ServerResponse, id?: string) => Promise<void> | void;
}

function matchRoute(path: string): { route: Route; id?: string } | undefined {
  if (path === '/') {
    return {
      route: {
        methods: ['GET'],
        handle: (_req, res) => {
          res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
          res.end(uiHtml);
        },
      },
    };
  }
  if (path === '/health') {
    return {
      route: {
        methods: ['GET'],
        handle: (_req, res) =>
          sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' }),
      },
    };
  }
  if (path === '/api/jobs') {
    return {
      route: {
        methods: ['GET', 'POST'],
        handle: (req, res) => {
          if (req.method === 'POST') return handleSubmit(req, res);
          sendJson(res, 200, { jobs: listJobs(db) });
        },
      },
    };
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return undefined;
    }
    return {
      route: {
        methods: ['GET'],
        handle: (_req, res) => {
          const job = getJob(db, id);
          if (!job) sendError(res, 404, 'not_found', 'Job not found.');
          else sendJson(res, 200, job);
        },
      },
      id,
    };
  }
  return undefined;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const matched = matchRoute(path);
  if (!matched) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  const method = req.method ?? 'GET';
  if (!matched.route.methods.includes(method)) {
    res.setHeader('Allow', matched.route.methods.join(', '));
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
    return;
  }
  await matched.route.handle(req, res, matched.id);
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) {
      sendError(res, 500, 'internal_error', 'Unexpected server error.');
    } else {
      res.end();
    }
  });
});

const port = Number(process.env.PORT || 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  console.log('server shutting down');
  let closed = false;
  const finish = () => {
    if (closed) return;
    closed = true;
    try {
      db.close();
    } catch {
      // already closed
    }
    process.exit(0);
  };
  server.close(finish);
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
  setTimeout(finish, SHUTDOWN_DEADLINE_MS).unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

