import { setInterval as every, clearInterval as stopEvery } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  MAX_ATTEMPTS,
  recordProgress,
  recordTransientFailure,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

/** Time for one processing step. */
const STEP_MS = 100;
/** Idle poll interval; a queued job is picked up within about this long. */
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt of a job. Failing attempts stop at their first step, before any progress. An
 * interrupted attempt is left `running` in the database and is replayed on the next start.
 */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    recordTransientFailure(db, job.seq, job.attempts, Date.now());
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
